local module = {}
module.__index = module

function module.new(eventBus: IEventBus, player: Player, protocolManager: IProtocolManager, env: IHostingEnvironment)
	local self = setmetatable({}, module)
	self.EventBus = eventBus
	self.ProtocolManager = protocolManager
	self.IsServer = env:IsServer()
	self.IsClient = not env:IsServer()
	self.Player = player
	return self
end

-- 发送协议
-- @param protocol: 协议名
-- @param dto: 协议数据
-- @param specificPlayer: 指定玩家，可选，默认发送给当前作用域玩家
function module:EmitProtocol(protocol: string, dto: {}, specificPlayer: Player?)
	assert(self.EventBus, "EventBus not provided")
	local protocolInfo = self.ProtocolManager:GetProtocol(protocol)
	assert(protocolInfo, "Protocol not found:" .. protocol)

	local type = protocolInfo.Type
	local eventBus: IEventBus = self.EventBus
	if type == "rpc" then
		assert(self.IsClient, "Protocol Request is not allowed on server")
		return eventBus.InvokeServer(protocol, dto)
	elseif type == "submit" then
		eventBus.FireServer(protocol, dto)
		assert(self.IsClient, "Protocol Submit is not allowed on server")
	elseif type == "notify" then
		assert(self.IsServer, "Protocol Notify is not allowed on client")
		eventBus.FireClient(self.Player, protocol, dto)
	elseif type == "notifySpecific" then
		assert(self.IsServer, "Protocol NotifySpecific is not allowed on client")
		assert(specificPlayer, "specificPlayer is required")
		eventBus.FireClient(specificPlayer, protocol, dto)
	elseif type == "notifyAll" then
		assert(self.IsServer, "Protocol NotifyAll is not allowed on client")
		eventBus.FireAllClients(protocol, dto)
	end
end

function module:Start() end

function module:Stop() end

return module
